/* Пасьянсы: Косынка (по одной и по три), Паук (1, 2 и 4 масти), Свободная ячейка.
   Стол — холст окна: карты тянутся мышью, щелчок отправляет карту, куда можно, двойной — в дом.
   Колода нарисована своя; книга и документ не меняются, статистика — в хранилище плагина. */
const Ш = 640, В = 560;
const МАСТИ = ['♠', '♥', '♦', '♣'], РАНГИ = ['', 'Т', '2', '3', '4', '5', '6', '7', '8', '9', '10', 'В', 'Д', 'К'];
const красная = к => к.м === 1 || к.м === 2;
const СТОЛ = '#1f6b4a', СТОЛ2 = '#1a5d40', МЕСТО = 'rgba(255,255,255,0.13)', РУБАШКА = '#2a5db0', ТЕКСТ = '#eef6f0';
const повод = () => (typeof книга !== 'undefined' && книга.повод) || (typeof документ !== 'undefined' && документ.повод) || {};
let п = null;            // партия
let тянем = null, подсказка = null, часы = null, сборка = null, нажато = null, вспышка = null, щелчок = null;

/* ---------- случайность: свой генератор по номеру расклада ---------- */
function генератор(seed){ let s = (seed >>> 0) || 1; return () => { s ^= s << 13; s >>>= 0; s ^= s >>> 17; s ^= s << 5; s >>>= 0; return s / 4294967296; }; }
function перемешать(м, rnd){ for(let i = м.length - 1; i > 0; i--){ const j = Math.floor(rnd() * (i + 1)); [м[i], м[j]] = [м[j], м[i]]; } return м; }
/* расклады «Свободной ячейки» по общепринятой нумерации 1…32000 (линейный конгруэнтный генератор) */
function раскладЯчейки(номер){
  let s = номер >>> 0;
  const rnd = () => { s = (Math.imul(s, 214013) + 2531011) >>> 0 & 0x7fffffff; return s >>> 16; };
  const колода = []; for(let i = 0; i < 52; i++) колода.push(i);
  const ряды = Array.from({length: 8}, () => []);
  const МС = [3, 2, 1, 0];            // порядок мастей в нумерации: ♣ ♦ ♥ ♠ → наши индексы
  for(let k = 0; k < 52; k++){
    const ост = 52 - k, j = rnd() % ост;
    const к = колода[j]; колода[j] = колода[ост - 1];
    ряды[k % 8].push({р: Math.floor(к / 4) + 1, м: МС[к % 4], откр: true});
  }
  return ряды;
}

/* ---------- раскладка стола ---------- */
const ВИДЫ = {
  'Косынка': {CW: 64, CH: 88, шаг: 86, x0: 22, верх: 44, ряды: 152, рядов: 7},
  'Паук': {CW: 56, CH: 78, шаг: 62, x0: 12, верх: 44, ряды: 140, рядов: 10},
  'Свободная ячейка': {CW: 64, CH: 88, шаг: 76, x0: 20, верх: 44, ряды: 152, рядов: 8},
};
const размер = () => ВИДЫ[п.вид];
function смещения(ряд){
  const {CH, ряды} = размер(), низ = В - 10;
  let закр = 9, откр = п.вид === 'Паук' ? 20 : 24;
  const nЗ = ряд.filter(к => !к.откр).length, nО = Math.max(0, ряд.length - nЗ - 1);
  if(ряды + nЗ * закр + nО * откр + CH > низ && nО){
    откр = Math.max(10, (низ - ряды - CH - nЗ * закр) / nО);
    if(откр === 10) закр = Math.max(4, (низ - ряды - CH - nО * откр) / Math.max(1, nЗ));
  }
  const см = [0];
  for(let i = 1; i < ряд.length; i++) см.push(см[i - 1] + (ряд[i - 1].откр ? откр : закр));
  return см;
}
/* все места стола: {вид, i, x, y, w, h} — для отрисовки и попадания */
function места(){
  const {CW, CH, шаг, x0, верх, ряды, рядов} = размер(), out = [];
  if(п.вид === 'Косынка'){
    out.push({вид: 'сток', i: 0, x: x0, y: верх, w: CW, h: CH});
    out.push({вид: 'сброс', i: 0, x: x0 + шаг, y: верх, w: CW + 30, h: CH});
    for(let i = 0; i < 4; i++) out.push({вид: 'дом', i, x: x0 + шаг * (3 + i), y: верх, w: CW, h: CH});
  } else if(п.вид === 'Свободная ячейка'){
    for(let i = 0; i < 4; i++) out.push({вид: 'ячейка', i, x: x0 + шаг * i, y: верх, w: CW, h: CH});
    for(let i = 0; i < 4; i++) out.push({вид: 'дом', i, x: x0 + шаг * (4 + i), y: верх, w: CW, h: CH});
  } else {
    out.push({вид: 'сток', i: 0, x: Ш - x0 - CW - 4 * 5, y: верх, w: CW + 20, h: CH});
    out.push({вид: 'дом', i: 0, x: x0, y: верх, w: CW + 7 * 22, h: CH});
  }
  for(let i = 0; i < рядов; i++){
    const р = п.ряды[i], см = смещения(р);
    out.push({вид: 'ряд', i, x: x0 + шаг * i, y: ряды, w: CW, h: р.length ? см[см.length - 1] + CH : CH, см});
  }
  return out;
}

/* ---------- новая партия ---------- */
function новаяПартия(вид, настр, номер){
  const ном = номер || (1 + Math.floor(Math.random() * 32000));
  const s = {вид, настр, номер: ном, ходов: 0, начало: 0, время: 0, победа: false, засчитано: false, история: [], сообщение: ''};
  if(вид === 'Свободная ячейка'){
    s.ряды = раскладЯчейки(ном); s.ячейки = [null, null, null, null]; s.дома = [[], [], [], []];
  } else if(вид === 'Косынка'){
    const rnd = генератор(ном * 2654435761);
    const колода = []; for(let м = 0; м < 4; м++) for(let р = 1; р <= 13; р++) колода.push({р, м, откр: false});
    перемешать(колода, rnd);
    s.ряды = []; for(let i = 0; i < 7; i++){ s.ряды.push(колода.splice(0, i + 1)); s.ряды[i][i].откр = true; }
    s.сток = колода; s.сброс = []; s.дома = [[], [], [], []]; s.потри = настр.косынка === 'По три карты';
  } else {
    const масти = настр.масти === 'Четыре масти' ? [0, 1, 2, 3] : настр.масти === 'Две масти' ? [0, 1] : [0];
    const rnd = генератор(ном * 2246822519 + масти.length);
    const колода = []; for(let k = 0; k < 104 / (13 * масти.length); k++) for(const м of масти) for(let р = 1; р <= 13; р++) колода.push({р, м, откр: false});
    перемешать(колода, rnd);
    s.ряды = []; for(let i = 0; i < 10; i++){ const n = i < 4 ? 6 : 5; const р = колода.splice(0, n); р[n - 1].откр = true; s.ряды.push(р); }
    s.сток = колода; s.дома = []; s.мастей = масти.length;
  }
  return s;
}
const ключСтат = s => s.вид === 'Косынка' ? 'Косынка (' + (s.потри ? 'по три' : 'по одной') + ')' : s.вид === 'Паук' ? 'Паук (' + ({1: '1 масть', 2: '2 масти', 4: '4 масти'})[s.мастей] + ')' : 'Свободная ячейка';

/* ---------- правила ---------- */
function последовательность(карты){
  for(let i = 1; i < карты.length; i++){
    const a = карты[i - 1], b = карты[i];
    if(!a.откр || !b.откр || a.р !== b.р + 1) return false;
    if(п.вид === 'Паук' ? a.м !== b.м : красная(a) === красная(b)) return false;
  }
  return карты.length > 0 && карты[0].откр;
}
function вместимость(вРяд){
  const св = п.ячейки.filter(x => !x).length;
  let пусто = п.ряды.filter(р => !р.length).length;
  if(вРяд) пусто--;
  return (св + 1) * Math.pow(2, Math.max(0, пусто));
}
function можноВзять(место, i){
  if(место.вид === 'ряд'){ const р = п.ряды[место.i]; return i >= 0 && i < р.length && последовательность(р.slice(i)); }
  if(место.вид === 'сброс') return п.сброс.length > 0;
  if(место.вид === 'дом') return п.вид !== 'Паук' && п.дома[место.i].length > 0;
  if(место.вид === 'ячейка') return !!п.ячейки[место.i];
  return false;
}
function можноПоложить(карты, место){
  const к = карты[0];
  if(место.вид === 'дом'){
    if(п.вид === 'Паук' || карты.length !== 1) return false;
    const д = п.дома[место.i];
    return д.length ? д[д.length - 1].м === к.м && к.р === д[д.length - 1].р + 1 : к.р === 1;
  }
  if(место.вид === 'ячейка') return карты.length === 1 && !п.ячейки[место.i];
  if(место.вид !== 'ряд') return false;
  if(место.родитель){ const в = место.родитель; return в.откр && в.р === к.р + 1 && (п.вид === 'Паук' ? в.м === к.м : красная(в) !== красная(к)); }
  const р = п.ряды[место.i];
  if(п.вид === 'Свободная ячейка' && карты.length > вместимость(!р.length)) return false;
  if(!р.length) return п.вид === 'Косынка' ? к.р === 13 : true;
  const в = р[р.length - 1];
  if(!в.откр || в.р !== к.р + 1) return false;
  return п.вид === 'Паук' ? true : красная(в) !== красная(к);
}
function снять(место, i){
  if(место.вид === 'ряд') return п.ряды[место.i].splice(i);
  if(место.вид === 'сброс') return [п.сброс.pop()];
  if(место.вид === 'дом') return [п.дома[место.i].pop()];
  if(место.вид === 'ячейка'){ const к = п.ячейки[место.i]; п.ячейки[место.i] = null; return [к]; }
  return [];
}
function положить(карты, место){
  if(место.вид === 'ряд') п.ряды[место.i].push(...карты);
  else if(место.вид === 'дом') п.дома[место.i].push(...карты);
  else if(место.вид === 'ячейка') п.ячейки[место.i] = карты[0];
}
function запомнить(){
  const копия = JSON.stringify({ряды: п.ряды, сток: п.сток, сброс: п.сброс, дома: п.дома, ячейки: п.ячейки, ходов: п.ходов});
  п.история.push(копия); if(п.история.length > 300) п.история.shift();
  if(!п.начало) п.начало = Date.now();
}
function открытьВерхние(){ for(const р of п.ряды) if(р.length && !р[р.length - 1].откр) р[р.length - 1].откр = true; }
function собратьМасти(){
  if(п.вид !== 'Паук') return 0;
  let n = 0;
  for(const р of п.ряды){
    if(р.length < 13) continue;
    const хвост = р.slice(-13);
    if(хвост[0].р === 13 && последовательность(хвост)){ р.splice(-13); п.дома.push(хвост[0].м); n++; }
  }
  if(n) открытьВерхние();
  return n;
}
function сделатьХод(откуда, i, куда){
  const карты = (откуда.вид === 'ряд') ? п.ряды[откуда.i].slice(i) : [верхняя(откуда)];
  if(!карты.length || !карты[0] || !можноПоложить(карты, куда)) return false;
  запомнить();
  положить(снять(откуда, i), куда);
  п.ходов++;
  открытьВерхние();
  собратьМасти();
  if(п.вид === 'Свободная ячейка') самоСбор();
  проверитьПобеду();
  return true;
}
function верхняя(место){
  if(место.вид === 'сброс') return п.сброс[п.сброс.length - 1];
  if(место.вид === 'дом') return п.вид === 'Паук' ? null : п.дома[место.i][п.дома[место.i].length - 1];
  if(место.вид === 'ячейка') return п.ячейки[место.i];
  if(место.вид === 'ряд'){ const р = п.ряды[место.i]; return р[р.length - 1]; }
  return null;
}
function изСтока(){
  if(п.вид === 'Косынка'){
    if(!п.сток.length && !п.сброс.length) return false;
    запомнить();
    if(п.сток.length){ const n = п.потри ? 3 : 1; for(let k = 0; k < n && п.сток.length; k++){ const к = п.сток.pop(); к.откр = true; п.сброс.push(к); } }
    else { п.сток = п.сброс.reverse().map(к => Object.assign(к, {откр: false})); п.сброс = []; }
    п.ходов++;
    return true;
  }
  if(п.вид === 'Паук'){
    if(!п.сток.length){ п.сообщение = 'Колода кончилась'; return false; }
    if(п.ряды.some(р => !р.length)){ п.сообщение = 'Перед раздачей заполните пустые ряды'; return false; }
    запомнить();
    for(const р of п.ряды){ const к = п.сток.pop(); к.откр = true; р.push(к); }
    п.ходов++;
    собратьМасти(); проверитьПобеду();
    return true;
  }
  return false;
}
/* безопасный самосбор «Свободной ячейки»: карта уходит в дом, если младшие карты другого цвета уже там */
function самоСбор(){
  for(let ещё = true; ещё;){
    ещё = false;
    const в = м => (п.дома.find(д => д.length && д[0].м === м) || []).length;
    const можно = к => к && (к.р <= 2 || (красная(к) ? Math.min(в(0), в(3)) >= к.р - 1 : Math.min(в(1), в(2)) >= к.р - 1));
    const источники = п.ряды.map((_, i) => ({вид: 'ряд', i})).concat(п.ячейки.map((_, i) => ({вид: 'ячейка', i})));
    for(const ист of источники){
      const к = верхняя(ист); if(!можно(к)) continue;
      const дом = домДля(к); if(!дом) continue;
      положить(снять(ист, ист.вид === 'ряд' ? п.ряды[ист.i].length - 1 : 0), дом); ещё = true;
    }
  }
}
function домДля(к){
  if(п.вид === 'Паук' || !к) return null;
  for(let i = 0; i < 4; i++){ const м = {вид: 'дом', i}; if(можноПоложить([к], м)) return м; }
  return null;
}
function вДомов(){ return п.вид === 'Паук' ? п.дома.length * 13 : п.дома.reduce((s, д) => s + д.length, 0); }
function проверитьПобеду(){
  if(п.победа || вДомов() < 52 * (п.вид === 'Паук' ? 2 : 1)) return;
  п.победа = true; п.время = Math.round((Date.now() - п.начало) / 1000);
  статистика(true);
}
function статистика(победа){
  if(п.засчитано || (!победа && !п.ходов)) return;
  п.засчитано = true;
  const все = хранилище.взять('статистика', null) || {}, к = ключСтат(п);
  const с = все[к] || {сыграно: 0, выиграно: 0, лучшее: 0, серия: 0, лучшаяСерия: 0};
  с.сыграно++;
  if(победа){ с.выиграно++; с.серия++; с.лучшаяСерия = Math.max(с.лучшаяСерия, с.серия); if(!с.лучшее || п.время < с.лучшее) с.лучшее = п.время; }
  else с.серия = 0;
  все[к] = с; хранилище.положить('статистика', все);
  показатьСтатистику();
}
function показатьСтатистику(){
  const все = хранилище.взять('статистика', null) || {};
  const строки = Object.keys(все).map(к => { const с = все[к]; return [к, с.выиграно + ' из ' + с.сыграно + (с.сыграно ? ' (' + Math.round(100 * с.выиграно / с.сыграно) + ' %)' : '') + (с.лучшее ? ', лучшее ' + мин(с.лучшее) : '') + (с.лучшаяСерия > 1 ? ', серия ' + с.лучшаяСерия : '')]; });
  панель.список('стат', строки.length ? строки : [['Пока не сыграно', '—']]);
}
const мин = с => Math.floor(с / 60) + ':' + String(с % 60).padStart(2, '0');

/* ---------- подсказка: какой ход полезен ---------- */
function найтиХод(){
  const ряды = п.ряды.map((_, i) => ({вид: 'ряд', i}));
  const цели = ряды.slice();
  if(п.вид !== 'Паук') for(let i = 0; i < 4; i++) цели.unshift({вид: 'дом', i});
  /* 1) в дом */
  if(п.вид !== 'Паук'){
    const ист = ряды.concat(п.вид === 'Косынка' ? [{вид: 'сброс', i: 0}] : п.ячейки.map((_, i) => ({вид: 'ячейка', i})));
    for(const s of ист){ const к = верхняя(s); const д = домДля(к); if(к && д) return {откуда: s, i: s.вид === 'ряд' ? п.ряды[s.i].length - 1 : 0, куда: д}; }
  }
  /* 2) ряд на ряд — если открывает карту, освобождает ряд или (паук) собирает масть */
  let запас = null, запас2 = null;
  for(const s of ряды){
    const р = п.ряды[s.i];
    for(let i = 0; i < р.length; i++){
      if(!можноВзять(s, i)) continue;
      for(const t of ряды){
        if(t.i === s.i || !можноПоложить(р.slice(i), t)) continue;
        const пустая = !п.ряды[t.i].length;
        if(пустая && i === 0) continue;                                    /* из ряда в пустой ряд целиком — бесполезно */
        const польза = (i > 0 && !р[i - 1].откр) || (i === 0 && !пустая) || (п.вид === 'Паук' && !пустая && п.ряды[t.i][п.ряды[t.i].length - 1].м === р[i].м && (i === 0 || р[i - 1].м !== р[i].м || р[i - 1].р !== р[i].р + 1));
        const ход = {откуда: s, i, куда: t};
        if(польза && !пустая) return ход;
        if(польза && !запас) запас = ход;
        const лишний = i > 0 && р[i - 1].откр && можноПоложить([р[i]], {вид: 'ряд', i: -1, родитель: р[i - 1]});
        if(!запас2 && !лишний && !пустая) запас2 = ход;
      }
      break;                                       /* брать имеет смысл только с первой возможной карты */
    }
  }
  if(запас) return запас;
  /* 3) из сброса или ячейки в ряд */
  const прочие = п.вид === 'Косынка' ? [{вид: 'сброс', i: 0}] : п.вид === 'Свободная ячейка' ? п.ячейки.map((_, i) => ({вид: 'ячейка', i})) : [];
  for(const s of прочие){ const к = верхняя(s); if(!к) continue; for(const t of ряды) if(можноПоложить([к], t)) return {откуда: s, i: 0, куда: t}; }
  if(п.вид !== 'Свободная ячейка' && (п.сток.length || (п.вид === 'Косынка' && п.сброс.length))) return {сток: true};
  return запас2;
}

/* ---------- отрисовка ---------- */
function карта(к, x, y, кар, подсв){
  const {CW, CH} = размер();
  к.push({вид: 'прямоугольник', x: x + 1, y: y + 2, ширина: CW, высота: CH, заливка: 'rgba(0,0,0,0.18)', скругление: 6});
  if(!кар.откр){
    к.push({вид: 'прямоугольник', x, y, ширина: CW, высота: CH, заливка: '#f4f6fb', скругление: 6, обводка: '#c8cfdc'});
    к.push({вид: 'прямоугольник', x: x + 4, y: y + 4, ширина: CW - 8, высота: CH - 8, заливка: РУБАШКА, скругление: 4});
    к.push({вид: 'путь', d: 'M' + (x + CW / 2) + ' ' + (y + 12) + 'L' + (x + CW - 12) + ' ' + (y + CH / 2) + 'L' + (x + CW / 2) + ' ' + (y + CH - 12) + 'L' + (x + 12) + ' ' + (y + CH / 2) + 'Z', обводка: 'rgba(255,255,255,0.35)', толщина: 1.5});
    return;
  }
  const цв = красная(кар) ? '#cf3434' : '#1d2433';
  к.push({вид: 'прямоугольник', x, y, ширина: CW, высота: CH, заливка: '#ffffff', скругление: 6, обводка: подсв || '#c8cfdc', толщина: подсв ? 3 : 1});
