/* ---------- попадание ---------- */
function попадание(x, y){
  const {CW, CH} = размер();
  const все = места();
  for(const м of все){
    if(м.вид === 'ряд'){
      const р = п.ряды[м.i];
      if(x < м.x || x > м.x + CW) continue;
      for(let i = р.length - 1; i >= 0; i--) if(y >= м.y + м.см[i] && y <= м.y + м.см[i] + CH) return {место: {вид: 'ряд', i: м.i}, i};
      if(!р.length && y >= м.y && y <= м.y + CH) return {место: {вид: 'ряд', i: м.i}, i: 0};
    } else if(м.вид === 'сброс'){
      const n = п.потри ? Math.min(3, п.сброс.length) : Math.min(1, п.сброс.length);
      const lx = м.x + Math.max(0, n - 1) * 15;
      if(x >= lx && x <= lx + CW && y >= м.y && y <= м.y + CH) return {место: {вид: 'сброс', i: 0}, i: 0};
    } else if(x >= м.x && x <= м.x + м.w && y >= м.y && y <= м.y + м.h) return {место: {вид: м.вид, i: м.i}, i: 0};
  }
  return null;
}
/* куда бросили: под точкой, а если там нельзя — место с наибольшим перекрытием, куда можно */
function цельБроска(x, y){
  const {CW, CH} = размер();
  const рx = x - тянем.dx, рy = y - тянем.dy;
  let лучшее = null, площадь = 0;
  for(const м of места()){
    if(!['ряд', 'дом', 'ячейка'].includes(м.вид) || (м.вид === тянем.откуда.вид && м.i === тянем.откуда.i)) continue;
    if(п.вид === 'Паук' && м.вид === 'дом') continue;
    const цель = {вид: м.вид, i: м.i};
    if(!можноПоложить(тянем.карты, цель)) continue;
    let вx = м.x, вy = м.y;
    if(м.вид === 'ряд' && п.ряды[м.i].length) вy = м.y + м.см[м.см.length - 1];
    const ш = Math.max(0, Math.min(рx + CW, вx + CW) - Math.max(рx, вx)), в = Math.max(0, Math.min(рy + CH, вy + CH + (м.вид === 'ряд' ? 40 : 0)) - Math.max(рy, вy));
    const пл = ш * в;
    if(x >= вx && x <= вx + CW && y >= м.y && y <= вy + CH + 30) return цель;
    if(пл > площадь){ площадь = пл; лучшее = цель; }
  }
  return площадь > CW * CH * 0.15 ? лучшее : null;
}
/* щелчок по карте: в дом, иначе в лучший ряд (сначала непустой), иначе (ячейка) — в свободную ячейку */
function умныйХод(место, i){
  if(!можноВзять(место, i)) return false;
  const карты = место.вид === 'ряд' ? п.ряды[место.i].slice(i) : [верхняя(место)];
  if(карты.length === 1 && место.вид !== 'дом'){ const д = домДля(карты[0]); if(д) return сделатьХод(место, i, д); }
  const ряды = п.ряды.map((_, j) => ({вид: 'ряд', i: j})).filter(t => !(место.вид === 'ряд' && t.i === место.i));
  const полные = ряды.filter(t => п.ряды[t.i].length && можноПоложить(карты, t));
  if(п.вид === 'Паук') полные.sort((a, b) => (верхняя(b).м === карты[0].м) - (верхняя(a).м === карты[0].м));
  if(полные.length) return сделатьХод(место, i, полные[0]);
  if(!(место.вид === 'ряд' && i === 0)){ const пуст = ряды.find(t => !п.ряды[t.i].length && можноПоложить(карты, t)); if(пуст) return сделатьХод(место, i, пуст); }
  if(п.вид === 'Свободная ячейка' && карты.length === 1 && место.вид !== 'ячейка'){ const я = п.ячейки.findIndex(x => !x); if(я >= 0) return сделатьХод(место, i, {вид: 'ячейка', i: я}); }
  return false;
}

