  const разбор = т => { const откр = !т.startsWith('#'); т = т.replace('#', ''); const м = МАСТИ.indexOf(т.slice(-1)); const р = РАНГИ.indexOf(т.slice(0, -1)); return {р, м, откр}; };
  if(д.ряды) п.ряды = д.ряды.map(р => р.map(разбор));
  if(д.дома) п.дома = п.вид === 'Паук' ? д.дома : д.дома.map(д2 => д2.map(разбор));
  if(д.сток) п.сток = д.сток.map(разбор);
  if(д.сброс) п.сброс = д.сброс.map(разбор);
  if(д.ячейки) п.ячейки = д.ячейки.map(x => x ? разбор(x) : null);
  п.история = [];
  нарисовать();
  return Состояние();
}
